$ErrorActionPreference = "Stop"

$iconBase64 = @'

'@

$assetsDir = Join-Path $PSScriptRoot "Assets"
$iconPath = Join-Path $assetsDir "urlscra.ico"
New-Item -ItemType Directory -Force -Path $assetsDir | Out-Null

[IO.File]::WriteAllBytes($iconPath, [Convert]::FromBase64String(($iconBase64 -replace '\s','')))
Write-Host "[URLScra] App icon ready: $iconPath"
